"""Suzuki RM-Z250 / RM-Z450 knowledge from public sources (magazine tests, tester baselines, Suzuki's own pages, and
values listed in third-party copies of owner's manuals), for public.bike_knowledge.

usage: python3 scripts/knowledge/rmz_public_rows.py            -> writes docs/research/expansion/suzuki/rmz-public-2026-11-20.json
       python3 scripts/knowledge/rmz_public_rows.py --payload  -> prints the compact payload and its md5 for the guarded insert
Each record is one fact for a model over a list of years ({y} in the text becomes the year). Every statement says who lists
the value; nothing here is presented as Suzuki-published unless the source is Suzuki's own page. Single-source values are
confidence low. Not applied to 2027 unless the record is about 2027 (Suzuki changed the suspension for 2027).
"""
import json,sys,hashlib,os
S={
 'mxa450_25':{'type':'magazine','name':'Motocross Action, race test of the 2025 Suzuki RM-Z450','url':'https://motocrossactionmag.com/mxa-race-test-2025-suzuki-rm-z450','date':'2025'},
 'mxa250_25':{'type':'magazine','name':'Motocross Action, race test of the 2025 Suzuki RM-Z250','url':'https://motocrossactionmag.com/mxa-race-test-2025-suzuki-rm-z250','date':'2025'},
 'mxa250_24':{'type':'magazine','name':'Motocross Action, race test of the 2024 Suzuki RM-Z250','url':'https://motocrossactionmag.com/mxa-race-test-2024-suzuki-rm-z250','date':'2024'},
 'dr450_25':{'type':'magazine','name':'Dirt Rider, 2025 Suzuki RM-Z450 RM Army Edition Technical Overview','url':'https://www.dirtrider.com/dirt-bikes/suzuki-rm-z450-rm-army-edition-technical-information/','date':'2025'},
 'dr450_23':{'type':'magazine','name':'Dirt Rider, 2023 Suzuki RM-Z450 Technical Information','url':'https://www.dirtrider.com/story/dirt-bikes/suzuki-rm-z450-technical-information-2023','date':'2023'},
 'keefer25':{'type':'tester','name':'Keefer Inc Testing, 2025 Suzuki RM-Z450 baseline settings','url':'https://www.keeferinctesting.com/?p=28578','date':'2025'},
 'keefer26':{'type':'tester','name':'Keefer Inc Testing, 2026 450 motocross baseline settings','url':'https://www.keeferinctesting.com/?p=29670','date':'2026'},
 'suz450_27':{'type':'manufacturer','name':'Suzuki, 2027 RM-Z450 model page','url':'https://suzukicycles.com/motocross/2027/rm-z450','date':'2026'},
 'um450_27':{'type':'magazine','name':'Ultimate Motorcycling, 2027 Suzuki RM-Z450 First Look','url':'https://ultimatemotorcycling.com/2026/07/09/2027-suzuki-rm-z450-first-look-yes-it-has-changes/','date':'2026-07-09'},
 'um250_27':{'type':'magazine','name':'Ultimate Motorcycling, 2027 Suzuki RM-Z250 Buyer\'s Guide','url':'https://ultimatemotorcycling.com/2026/10/21/2027-suzuki-rm-z250-buyers-guide/','date':'2026-10-21'},
 'dr27':{'type':'magazine','name':'Dueruote, Suzuki rinnova le RM-Z 2027','url':'https://www.dueruote.it/news/moto-scooter/2026/07/09/suzuki-rinnova-le-rm-z-2027-ecco-le-novita/','date':'2026-07-09'},
 'om450b':{'type':'manual_copy','name':"Suzuki RM-Z450 owner's manual, later US/Canada edition (third-party copy, ManualsLib 3539725)",'url':'https://www.manualslib.com/manual/3539725/Suzuki-Rm-Z450.html','date':'n.d.'},
 'om250':{'type':'manual_copy','name':"Suzuki RM-Z250 owner's manual, 2019+ edition (third-party copy, ManualsLib 3557200)",'url':'https://www.manualslib.com/manual/3557200/Suzuki-Rm-Z250.html','date':'n.d.'},
}
Y=lambda a,b:list(range(a,b+1))
ONE=' (one source; not from a Suzuki-published document, so treat as a starting point and verify)'
R=[]
def rec(i,model,years,domain,topic,statement,vals,src,conf,notes,tier='COMMUNITY'):
    R.append({'id':i,'model':model,'years':years,'domain':domain,'topic':topic,'statement':statement,'vals':vals,'tier':tier,'sources':src,'confidence':conf,'notes':notes})
# ---- RM-Z450 ----
rec('rmzp-450-01','RM-Z450',Y(2022,2026),'suspension','stock shock spring rate','Stock shock spring rate: 54 N/mm on the {y} RM-Z450, as listed by magazine and tester setup sheets (not from a Suzuki-published source). One 2023 spec table and one owner\'s-manual copy list 56 N/mm instead, so check the marking on the spring before ordering a different rate.',{'shock_spring_n_mm':54,'also_listed_n_mm':56},['dr450_25','keefer25','keefer26','mxa450_25'],'medium','Dirt Rider 2025 lists 54 and says the shock spring rate has been the same since 2019; Keefer 2025 and 2026 baselines use 54. Dirt Rider 2023 and a later manual copy list 56.')
rec('rmzp-450-02','RM-Z450',[2025,2026],'setups','tester baseline, motocross','Tester baseline for the {y} RM-Z450 (Keefer Inc Testing, stock valving): fork 5.0 N/mm springs, fork height 3-5 mm up in the clamps, compression 9 clicks out, rebound 14 clicks out; shock 54 N/mm spring, race sag 105 mm, compression 1.25 turns out, rebound 1.5 turns out. The BFRC shock has one compression adjuster (no separate high-speed).',{'fork_spring_n_mm':5.0,'fork_height_mm':[3,5],'fork_compression_clicks_out':9,'fork_rebound_clicks_out':14,'shock_spring_n_mm':54,'race_sag_mm':105,'shock_compression_turns_out':1.25,'shock_rebound_turns_out':1.5},['keefer25','keefer26'],'medium','Same tester, 2025 and 2026 articles; the 2026 article says the setting has not changed. A tester\'s setting, not the factory standard.','TUNER')
rec('rmzp-450-03','RM-Z450',Y(2020,2026),'identity','what changed by year','Model history as reported by magazine tests: the current RM-Z450 arrived for 2018, got a softer shock spring for 2019, and was mechanically unchanged from 2020 through 2025 (changes were graphics and editions). A tester\'s 2026 baseline says his settings did not change from 2025. Setup advice and parts for any 2019-2026 RM-Z450 generally carry across those years.',{'platform_first_year':2018,'mechanically_unchanged':[2020,2025]},['mxa450_25','dr450_23','dr450_25','keefer26'],'high','MXA 2025: unchanged 2020-2024, no changes for 2025. Dirt Rider 2023: 2019-2022 revisions strictly cosmetic, 2023 completely unchanged. Dirt Rider 2025: last mechanical revisions 2019.')
rec('rmzp-450-04','RM-Z450',Y(2020,2026),'known_issues','clutch slip','Testers report the stock clutch on the RM-Z450 slips under hard use; the common fix they give is stiffer (heavier) clutch springs.',{},['mxa450_25'],'low','Motocross Action 2025 race test; the bike is mechanically unchanged 2020-2025.')
rec('rmzp-450-05','RM-Z450',Y(2020,2026),'known_issues','coolant loss in long motos','Testers report the RM-Z450 can lose coolant in long motos. They list the stock radiator cap at 1.1 kg/cm2 and fit a higher-pressure cap (1.8 to 2.0 kg/cm2) to stop it.',{'stock_radiator_cap_kg_cm2':1.1,'tester_cap_kg_cm2':[1.8,2.0]},['mxa450_25'],'low','Motocross Action 2025 race test.')
rec('rmzp-450-06','RM-Z450',Y(2020,2026),'setups','gearing tip from testers','Stock gearing is 13/50. Motocross Action ran 13/51 (one tooth more on the rear) to help the engine pull, and short-shifted to keep it between about 7,000 and 8,800 rpm because power falls off above about 9,000 rpm.',{'stock':[13,50],'tester':[13,51]},['mxa450_25','dr450_25'],'medium','Stock 13/50 is listed by both Motocross Action and Dirt Rider (2025); 13/51 is Motocross Action\'s choice.','TUNER')
rec('rmzp-450-07','RM-Z450',Y(2020,2026),'known_issues','shock and fork character','Testers describe the stock Showa BFRC shock as harsh over consecutive bumps and prone to a rebound kick, and the stock fork as worth a re-valve. Motocross Action ran the fork flush with the top of the clamps and a longer aftermarket shock linkage to lower the rear and calm headshake.',{},['mxa450_25'],'low','Motocross Action 2025 race test; opinion of one test crew.')
rec('rmzp-450-08','RM-Z450',[2023],'power_feel','measured power and weight','Measured by Dirt Rider on a 2023 RM-Z450: 50.9 hp at 8,500 rpm and 33.7 lb-ft at 7,300 rpm on their dyno; 251 lb wet with a full tank; seat height 37.1 in; stock header and muffler 9.2 lb.',{'hp':50.9,'hp_rpm':8500,'torque_lb_ft':33.7,'torque_rpm':7300,'wet_weight_lb':251},['dr450_23'],'medium','One magazine\'s dyno and scale; dyno numbers differ between dynos.','MEASURED')
rec('rmzp-450-09','RM-Z450',[2025],'power_feel','measured power and weight','Measured on 2025 RM-Z450 test bikes: Dirt Rider 52.8 hp at 9,100 rpm and 33.9 lb-ft at 7,100 rpm, 250 lb wet; Motocross Action 241 lb without fuel. Dyno numbers differ between dynos.',{'hp':52.8,'hp_rpm':9100,'torque_lb_ft':33.9,'torque_rpm':7100,'wet_weight_lb':250,'weight_no_fuel_lb':241},['dr450_25','mxa450_25'],'medium','Two magazines, each on its own dyno and scale.','MEASURED')
rec('rmzp-450-10','RM-Z450',Y(2020,2023),'chassis','suspension, brakes and tires as tested','As listed for the unchanged 2019-2025 RM-Z450 by Dirt Rider: Showa 49 mm coil-spring fork (12.0 in travel) and Showa BFRC shock (12.3 in travel); Nissin brakes with 270 mm front and 240 mm rear discs; Bridgestone Battlecross X30 tires, 80/100-21 front and 110/90-19 rear; wheelbase 58.3 in; rake 27.8 degrees, trail 4.7 in; 1.7 gal tank.',{'fork_travel_in':12.0,'shock_travel_in':12.3,'front_disc_mm':270,'rear_disc_mm':240,'wheelbase_in':58.3,'rake_deg':27.8,'trail_in':4.7},['dr450_23','dr450_25'],'medium','Same figures in the 2023 and 2025 spec tables; magazines report no mechanical change 2020-2025.')
rec('rmzp-450-11','RM-Z450',[2025,2026],'ecu_electronics','couplers and MX-Tuner','The RM-Z450 comes with three plug-in fuel couplers (stock, aggressive, mellow). Maps can also be changed with Suzuki\'s MX-Tuner phone app; testers note it needs an external battery to power the bike\'s electronics while tuning because the bike has no battery.',{},['mxa450_25'],'low','Motocross Action 2025 race test.')
for i,(topic,st,vals) in enumerate([
 ('rear axle nut torque','Rear axle nut: 100 N·m (74 lbf-ft)',{'rear_axle_nut_nm':100}),
 ('engine oil drain plug torque','Engine oil drain plug: 12 N·m (9 lbf-ft)',{'oil_drain_plug_nm':12}),
 ('oil strainer cap torque','Oil strainer cap: 21 N·m (15.5 lbf-ft)',{'oil_strainer_cap_nm':21}),
 ('spark plug torque','Spark plug: 11 N·m (8 lbf-ft)',{'spark_plug_nm':11}),
 ('rim lock (bead stopper) nut torque','Rim lock (bead stopper) nut: 14 N·m (10.5 lbf-ft)',{'bead_stopper_nm':14}),
 ('idle speed','Engine idle speed: 2,100 +/- 50 rpm',{'idle_rpm':2100}),
 ('tire pressure range','Tire pressure (cold): 70-110 kPa (10-16 psi), front and rear',{'tire_kpa':[70,110],'tire_psi':[10,16]}),
 ('service intervals','Service intervals for racing use: change the engine oil every 6 hours; inspect the piston and rings and check valve clearance every 12 hours',{'oil_change_hours':6,'piston_valve_check_hours':12})],start=20):
    rec(f'rmzp-450-{i}','RM-Z450',Y(2020,2026),'maintenance',topic,st+', as listed in a third-party copy of the RM-Z450 owner\'s manual'+ONE+'.',vals,['om450b'],'low','Single manual copy whose model year is not printed (file dated 2023); no second independent match found. The platform is mechanically unchanged 2020-2025.')
rec('rmzp-450-40','RM-Z450',[2027],'identity','what changed for 2027','The 2027 RM-Z450 is not the same bike as 2018-2026 underneath: Suzuki lists a KYB coil-spring fork and KYB shock with new settings in place of the Showa fork and BFRC shock, new RK Excel rims, a revised intake port, a straighter handlebar bend and MX-Tuner 4.0; a magazine first look adds a new upper triple clamp and a new muffler on a narrower subframe. Clicker settings, sag and spring rates published for 2018-2026 bikes do not apply to the 2027 suspension.',{'fork':'KYB coil spring','shock':'KYB'},['suz450_27','um450_27','dr27'],'high','Suzuki\'s own 2027 model page plus two magazine reports. No public stock clicker or spring figures for the 2027 KYB parts were found as of 2026-11-20.')
# ---- RM-Z250 ----
rec('rmzp-250-01','RM-Z250',Y(2020,2025),'identity','what changed by year','Model history as reported by Motocross Action: the current RM-Z250 arrived for 2019 (new frame, KYB coil-spring fork, larger front brake rotor, dual injectors, new shock, revised cylinder head and gear ratios) and had no mechanical changes through 2025. Setup advice and parts for any 2019-2025 RM-Z250 generally carry across those years.',{'platform_first_year':2019,'mechanically_unchanged':[2020,2025]},['mxa250_24','mxa250_25'],'medium','Motocross Action 2024 and 2025 race tests (one publication).')
rec('rmzp-250-02','RM-Z250',Y(2020,2025),'known_issues','fork too stiff for most riders','Testers find the stock 5.0 N/mm fork springs and valving too stiff for most 250 riders. Motocross Action\'s quick fix is lowering the fork oil level by 30 mm in each leg; the fuller fix they give is softer springs and a re-valve.',{'stock_fork_spring_n_mm':5.0,'oil_level_change_mm':-30},['mxa250_24','mxa250_25'],'medium','Same advice in the 2024 and 2025 race tests (one publication).')
rec('rmzp-250-03','RM-Z250',Y(2020,2025),'known_issues','clutch, brake, frame and shifting','Reported by Motocross Action on the RM-Z250: the clutch starts to slip after a few hours (fix: stiffer aftermarket clutch springs); the front brake lacks power and fades; the aluminium frame feels rigid (they fitted aftermarket engine mounts); shifting is notchy under load; and with no electric start a stall costs time.',{},['mxa250_25'],'low','Motocross Action 2025 race test; opinion of one test crew.')
rec('rmzp-250-04','RM-Z250',[2024,2025],'power_feel','measured power and weight','Measured by Motocross Action on RM-Z250 test bikes: 227 lb without fuel (2024 and 2025); 39.52 peak hp on their dyno (2025), the lowest in the class. Testers short-shift it to stay in the mid-range.',{'weight_no_fuel_lb':227,'hp':39.52},['mxa250_24','mxa250_25'],'medium','One magazine\'s dyno and scale.','MEASURED')
rec('rmzp-250-05','RM-Z250',[2024,2025],'ecu_electronics','couplers and MX-Tuner','The RM-Z250 comes with three plug-in fuel couplers; testers say the white one is the most aggressive off the bottom. Suzuki\'s MX-Tuner 2.0 phone app adds four preset maps (aggressive, smooth, richer, leaner) and custom fuel and ignition maps; it needs a separately sold battery and cable to power the ECU. Motocross Action preferred Pro Circuit\'s map over stock.',{},['mxa250_24','mxa250_25'],'medium','2024 and 2025 race tests (one publication).')
for i,(topic,st,vals) in enumerate([
 ('engine oil quantity','Engine oil: 950 ml at an oil change, 1,000 ml with a filter change, 1,100 ml after an engine overhaul',{'oil_change_ml':950,'oil_with_filter_ml':1000,'oil_overhaul_ml':1100}),
 ('coolant capacity','Coolant capacity: 1,100 ml (1.2 US qt)',{'coolant_ml':1100}),
 ('spark plug torque','Spark plug: 11 N·m (8 lbf-ft)',{'spark_plug_nm':11}),
 ('shock spring set length','Standard shock spring set (installed) length: 242 mm',{'shock_spring_set_length_mm':242}),
 ('fork oil quantity range and type','Fork oil quantity adjustable range: 310-375 ml per leg; fork oil Suzuki L-05 or equivalent',{'fork_oil_ml_range':[310,375]})],start=20):
    rec(f'rmzp-250-{i}','RM-Z250',Y(2020,2026),'maintenance' if i!=23 and i!=24 else 'suspension',topic,st+', as listed in a third-party copy of the 2019+ RM-Z250 owner\'s manual'+ONE+'.',vals,['om250'],'low','Single manual copy; no second independent match found.')
rec('rmzp-250-40','RM-Z250',[2027],'identity','what changed for 2027','The 2027 RM-Z250 has new KYB fork and shock settings (both fork legs now carry the same springs and damping parts), new Excel rims with Dunlop Geomax MX34 tires, a new quieter muffler, subframe rails moved to fit a larger air cleaner, and footpegs and grips moved slightly; listed at 233 lb wet with a 58.5 in wheelbase and 37.6 in seat. Clicker settings and oil levels published for 2019-2026 bikes may not suit the 2027 suspension.',{'wet_weight_lb':233,'wheelbase_in':58.5,'seat_height_in':37.6},['um250_27','dr27'],'medium','Two magazine reports of Suzuki\'s 2027 announcement. No public stock clicker figures for the 2027 settings were found as of 2026-11-20.')
def rows():
    out=[]
    for r in R:
        s=[S[k] for k in r['sources']]
        for y in r['years']:
            out.append({'id':f"{r['id']}|Suzuki|{r['model']}|{y}",'manufacturer':'Suzuki','model':r['model'],'model_year':y,'domain':r['domain'],'topic':f"{y} {r['model']} {r['topic']}",'statement':r['statement'].replace('{y}',str(y)),'vals':r['vals'],'tier':r['tier'],'source':{**s[0],**({'corroborating':s[1:]} if len(s)>1 else {})},'confidence':r['confidence'],'notes':r['notes'],'status':'APPROVED','research_id':r['id']})
    return out
if '--payload' in sys.argv:
    j=json.dumps({'sources':S,'records':R},ensure_ascii=False,separators=(',',':'));print(hashlib.md5(j.encode()).hexdigest(),len(j),len(rows()));open(sys.argv[sys.argv.index('--payload')+1],'w').write(j)
else:
    root=os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    json.dump({'title':'Suzuki RM-Z250 / RM-Z450 from public sources','date':'2026-11-20','rule':'Every statement names who lists the value. Single-source values are confidence low. 2018-2026 suspension values are not applied to 2027.','sources':S,'records':R,'rows':rows()},open(os.path.join(root,'docs/research/expansion/suzuki/rmz-public-2026-11-20.json'),'w'),indent=1,ensure_ascii=False)
    print(len(R),'records',len(rows()),'rows')
